// Live fitting in the browser: the same Rust core as the CLI, compiled to wasm.
// Data slices are generated by scripts/make_docs_figures.py --bundle-slice, as real
// gzipped NIfTI-1 files; NiiVue reads and displays them directly (no reimplemented
// NIfTI parsing here). The only array handling this file owns is the flattening
// between a loaded NVImage's native voxel order and `fit_volume`'s C-order
// `[nx,ny,nz,nt]` contract (see crates/qmrust-wasm/src/api.rs), and a generic
// YAML-tree walk that turns a model's recipe into form widgets without ever
// naming a model or parameter.
import { Niivue, NVImage } from "./vendor/niivue.js";
import { load as yamlLoad, dump as yamlDump } from "./vendor/js-yaml.js";

const $ = (id) => document.getElementById(id);
const status = (m, isError = false) => {
  const el = $("status");
  el.textContent = m;
  el.classList.toggle("error", isError);
};

// Colormap per output unit, never per model/output name — mirrors
// scripts/docsfig/style.py's CMAP_BY_UNIT so the playground and the static
// figures agree. Only used as a *default*; the dropdown lets a reader
// override it with any colormap the vendored build actually ships.
const CMAP_BY_UNIT = { s: "magma", "1/s": "viridis", "%": "cividis", "": "inferno" };
const CANDIDATE_COLORMAPS = ["gray", "viridis", "magma", "inferno", "plasma", "hot", "cool", "turbo", "cividis"];

let wasm = null;
const bundleCache = {};
let current = null; // { meta, volume (NVImage), maskU8 (Uint8Array|null), frame }
let lastMaps = null; // { [outputName]: Float64Array }, C-order [nx,ny,nz] — every
// entry fit_volume returns, i.e. the model's full output_names(), not just the
// quantitative maps in meta.outputs.
let outputVolumes = []; // [{ name, unit, volume, defaultCalMin, defaultCalMax }]
let shownOutput = null; // the outputVolumes entry currently drawn in the fitted-map viewer
let availableColormaps = [];
// Config keys restricted to a fixed set of values (dotted path -> allowed
// values), from this model's bundle `enums` — the catalog/registry decides
// which keys get a dropdown, never a name or key hard-coded here.
let enumFields = new Map();
// Accumulated wheel `deltaY` for the inputs viewer's frame-step gesture (see
// the `wheel` listener in `main`); reset on every model load so a gesture
// mid-flight on the old model can't carry a partial step into the new one.
let wheelAccum = 0;
const WHEEL_STEP_THRESHOLD = 100;

// Recipe editor state: `text` is always the source of truth handed to
// fit_volume; `obj` is its parsed form (null while the text is invalid).
const editor = { text: "", obj: null, valid: false };

// The inputs viewer shows an acquired image, so linear interpolation (the
// default) is the right look. The fitted-map viewer shows per-voxel
// quantitative values with hard NaN boundaries at the mask edge; blending
// those linearly with neighboring voxels invents in-between colours at the
// boundary that were never fitted, so it uses nearest-neighbour instead —
// every displayed pixel is then one real fitted value.
const nvIn = new Niivue({ isResizeCanvas: true, backColor: [0.02, 0.02, 0.03, 1] });
const nvOut = new Niivue({
  isResizeCanvas: true,
  backColor: [0.02, 0.02, 0.03, 1],
  isColorbar: true,
  isNearestInterpolation: true,
});

async function loadWasm() {
  try {
    const mod = await import("./pkg/qmrust_wasm.js");
    await mod.default();
    return mod;
  } catch (e) {
    $("fallback").hidden = false;
    status("wasm unavailable — viewers still work, fitting does not");
    return null;
  }
}

async function fetchOrThrow(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: ${r.status}`);
  return r;
}

async function loadBundle(name) {
  if (bundleCache[name]) return bundleCache[name];
  const meta = await (await fetchOrThrow(`./data/${name}.json`)).json();
  bundleCache[name] = meta;
  return meta;
}

// ---------------------------------------------------------------------------
// Recipe editor: a generic walk over the parsed YAML tree. Nothing here
// branches on a model, parameter, or key name — every widget kind is chosen
// purely from the JS type of the value found at that path.

function getAtPath(root, path) {
  let node = root;
  for (const k of path) node = node?.[k];
  return node;
}

function setAtPath(root, path, value) {
  let node = root;
  for (const k of path.slice(0, -1)) node = node[k];
  node[path.at(-1)] = value;
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function isNumberArray(v) {
  return Array.isArray(v) && v.every((x) => typeof x === "number");
}

// Re-derives `editor.text` from `editor.obj` after a form edit, and refreshes
// the (possibly hidden) YAML textarea + status pill to match.
function commitObjEdit() {
  editor.text = yamlDump(editor.obj);
  editor.valid = true;
  $("cfg-yaml").value = editor.text;
  setYamlPill(true);
}

function fieldRow(label, path, widget) {
  const row = document.createElement("div");
  row.className = "field-row";
  const labelWrap = document.createElement("div");
  const labelSpan = document.createElement("span");
  labelSpan.className = "field-label";
  labelSpan.textContent = label.replace(/_/g, " ");
  const keySpan = document.createElement("span");
  keySpan.className = "field-key";
  keySpan.textContent = path.join(".");
  labelWrap.append(labelSpan, keySpan);
  row.append(labelWrap, widget);
  return row;
}

function buildWidget(value, path) {
  const enumValues = enumFields.get(path.join("."));
  if (enumValues && typeof value === "string") {
    const select = document.createElement("select");
    for (const opt of enumValues) {
      const o = document.createElement("option");
      o.value = opt;
      o.textContent = opt;
      select.append(o);
    }
    select.value = value;
    select.onchange = () => {
      setAtPath(editor.obj, path, select.value);
      commitObjEdit();
    };
    return select;
  }
  if (typeof value === "boolean") {
    const label = document.createElement("label");
    label.className = "switch";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = value;
    input.onchange = () => {
      setAtPath(editor.obj, path, input.checked);
      commitObjEdit();
    };
    const slider = document.createElement("span");
    slider.className = "slider";
    label.append(input, slider);
    return label;
  }
  if (typeof value === "number") {
    const input = document.createElement("input");
    input.type = "number";
    input.step = "any";
    input.value = String(value);
    input.onchange = () => {
      const v = Number(input.value);
      setAtPath(editor.obj, path, Number.isFinite(v) ? v : value);
      commitObjEdit();
    };
    return input;
  }
  if (isNumberArray(value)) {
    const input = document.createElement("input");
    input.type = "text";
    input.value = value.join(", ");
    input.onchange = () => {
      const parsed = input.value
        .split(",")
        .map((s) => Number(s.trim()))
        .filter((n) => !Number.isNaN(n));
      setAtPath(editor.obj, path, parsed);
      commitObjEdit();
    };
    return input;
  }
  if (typeof value === "string") {
    const input = document.createElement("input");
    input.type = "text";
    input.value = value;
    input.onchange = () => {
      setAtPath(editor.obj, path, input.value);
      commitObjEdit();
    };
    return input;
  }
  // Fallback for shapes a compact widget can't represent (array of arrays,
  // array of objects, null): a small YAML textarea for just that subtree.
  const ta = document.createElement("textarea");
  ta.value = value == null ? "" : yamlDump(value).trimEnd();
  ta.onchange = () => {
    try {
      const parsed = ta.value.trim() === "" ? null : yamlLoad(ta.value);
      setAtPath(editor.obj, path, parsed);
      commitObjEdit();
    } catch (e) {
      // Leave the underlying object untouched; the textarea keeps the
      // reader's (currently unparsable) text so they can keep fixing it.
    }
  };
  return ta;
}

function buildGroup(container, entries, path) {
  for (const [key, value] of entries) {
    // `model` at the config root is the reserved key that selects the model
    // itself — part of the config format, not a per-model field — and the
    // model dropdown above the recipe editor already owns it, so a form row
    // for it here would just be a redundant, editable duplicate.
    if (path.length === 0 && key === "model") continue;
    const childPath = [...path, key];
    if (isPlainObject(value)) {
      const group = document.createElement("div");
      group.className = "group";
      const title = document.createElement("div");
      title.className = "group-title";
      title.textContent = key;
      const fields = document.createElement("div");
      fields.className = "form-fields";
      group.append(title, fields);
      buildGroup(fields, Object.entries(value), childPath);
      container.append(group);
    } else {
      container.append(fieldRow(key, childPath, buildWidget(value, childPath)));
    }
  }
}

function renderForm() {
  const container = $("form-fields");
  container.replaceChildren();
  if (!editor.obj || typeof editor.obj !== "object") return;
  buildGroup(container, Object.entries(editor.obj), []);
}

function setYamlPill(valid) {
  const pill = $("yaml-pill");
  pill.textContent = valid ? "valid" : "invalid";
  pill.classList.toggle("valid", valid);
  pill.classList.toggle("invalid", !valid);
}

// Sets the editor from a fresh string (model load, or typed into the YAML
// view). Rebuilds the form only when the text parses, so a reader mid-typo
// in the YAML view doesn't have the form yanked out from under them.
function setEditorText(text) {
  editor.text = text;
  $("cfg-yaml").value = text;
  try {
    editor.obj = yamlLoad(text);
    editor.valid = true;
    setYamlPill(true);
    renderForm();
  } catch (e) {
    editor.valid = false;
    setYamlPill(false);
  }
}

function showTab(tab) {
  const isForm = tab === "form";
  $("tab-form").classList.toggle("active", isForm);
  $("tab-yaml").classList.toggle("active", !isForm);
  $("tab-form").setAttribute("aria-selected", String(isForm));
  $("tab-yaml").setAttribute("aria-selected", String(!isForm));
  $("form-view").hidden = !isForm;
  $("yaml-view").hidden = isForm;
  if (isForm && editor.valid) renderForm();
}

// ---------------------------------------------------------------------------

// Every element of `flat` (C-order `[nx,ny,nz]`, i.e. index `(x*ny+y)*nz+z`,
// matching fit_volume's own output convention) read from `volume` via its
// public accessor, so slope/intercept and orientation are handled exactly as
// NiiVue would for display — no separate raw-buffer indexing to get wrong.
// These bundles carry no qform/sform (a single downsampled slice has no
// meaningful scanner orientation), so NiiVue's own axis order is already
// native `dim[1]`/`dim[2]` order — the same order `fit_volume`, the output
// maps, and the `probes` oracle all use.
function readVolumeSeries(volume, nx, ny, nz, nt) {
  const flat = new Float64Array(nx * ny * nz * nt);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        for (let t = 0; t < nt; t++) {
          flat[((x * ny + y) * nz + z) * nt + t] = volume.getValue(x, y, z, t);
        }
      }
    }
  }
  return flat;
}

// C-order `[nx,ny,nz]`, single frame — the same convention `readVolumeSeries`
// uses per timepoint, and the one `fit_volume`'s `mask`/`aux` arguments want.
function readScalarVolume(volume, nx, ny, nz) {
  const flat = new Float64Array(nx * ny * nz);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        flat[(x * ny + y) * nz + z] = volume.getValue(x, y, z, 0);
      }
    }
  }
  return flat;
}

function readMask(volume, nx, ny, nz) {
  const raw = readScalarVolume(volume, nx, ny, nz);
  return Uint8Array.from(raw, (v) => (v > 0 ? 1 : 0));
}

// Fixed 2nd/98th-percentile window over the finite (in-mask, fitted) values —
// the same rule `scripts/docsfig/style.py`'s `window()` uses for the
// committed figures, so the browser and the published figures agree, and a
// few boundary-stuck fit failures (e.g. a grid search pinned at its T1 upper
// bound) cannot single-handedly drag the whole map's range out to them the
// way a plain min/max would.
function percentileWindow(values) {
  const finite = [];
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (Number.isFinite(v)) finite.push(v);
  }
  if (finite.length === 0) return [0, 1];
  finite.sort((a, b) => a - b);
  const at = (p) => {
    const idx = (p / 100) * (finite.length - 1);
    const lo = Math.floor(idx);
    const hi = Math.ceil(idx);
    return lo === hi ? finite[lo] : finite[lo] + (finite[hi] - finite[lo]) * (idx - lo);
  };
  const lo = at(2);
  const hi = at(98);
  return hi > lo ? [lo, hi] : [lo, lo + 1];
}

// Rounds a colour-scale bound to ~3 significant figures for display in the
// min/max inputs — full float precision is not a meaningful "default", and
// doesn't fit the input box either.
function roundBound(v) {
  if (!Number.isFinite(v) || v === 0) return 0;
  const digits = Math.max(0, 2 - Math.floor(Math.log10(Math.abs(v))));
  return Number(v.toFixed(Math.min(6, digits)));
}

// Build a displayable NVImage for one output map from `flat` (C-order
// `[nx,ny,nz]`, NaN outside the fit), reusing `template`'s header/orientation
// (NVImage.zerosLike) rather than hand-rolling a NIfTI header.
function buildMapVolume(template, flat, nx, ny, nz, name, unit) {
  const vol = NVImage.zerosLike(template, "float32");
  vol.hdr.dims = template.hdr.dims.slice();
  vol.hdr.dims[0] = 3;
  vol.hdr.dims[4] = 1;
  vol.nFrame4D = 1;
  const [lo, hi] = percentileWindow(flat);
  // Unfitted voxels (NaN — outside the mask, or a failed fit) must not read
  // as the *brightest* colour in the map, which is what an unclamped NaN
  // texel does here. Park them well below the display window so they clamp
  // to the colormap's dark end instead — the GPU equivalent of
  // `docsfig.style`'s `cm.set_bad(BG)`.
  const sentinel = lo - Math.max(1, hi - lo);
  const img = new Float32Array(nx * ny * nz);
  for (let x = 0; x < nx; x++) {
    for (let y = 0; y < ny; y++) {
      for (let z = 0; z < nz; z++) {
        const v = flat[(x * ny + y) * nz + z];
        img[x + y * nx + z * nx * ny] = Number.isFinite(v) ? v : sentinel;
      }
    }
  }
  vol.img = img;
  vol.name = `${name}${unit ? ` [${unit}]` : ""}`;
  // Trust the percentile window computed above rather than have NiiVue
  // recompute its own min/max from the raw buffer — which would include the
  // dark-end sentinel just written in for NaN and pull the window back out
  // to it.
  vol.trustCalMinMax = true;
  vol.colorbarVisible = true;
  vol.calculateRAS();
  // `NVImage.zerosLike` clones `template` (the acquired image) before
  // zeroing it, and `clone()` runs the library's own `calMinMax()` over the
  // *template's* data as a side effect — so `hdr.cal_min`/`hdr.cal_max` start
  // out describing the wrong image entirely. Set both the plain property and
  // its header twin to our percentile window, so whichever one a later
  // render/add-volume step reads back gets the fitted map's own range.
  vol.cal_min = roundBound(lo);
  vol.cal_max = roundBound(hi);
  vol.hdr.cal_min = vol.cal_min;
  vol.hdr.cal_max = vol.cal_max;
  return vol;
}

// The two viewer wraps are equal-width grid columns, stretched (CSS
// `align-items: stretch`) to the grid row's full height, with `.viewer`
// flexed to fill that in turn — so both viewers are always exactly the same
// size, whatever space the page has to give them. NiiVue fits a slice inside
// whatever box it is given, preserving the data's own aspect ratio (fit-to-
// contain, like an `object-fit: contain` image), so the box itself does not
// need to match the data's aspect ratio the way it used to.
function sizeViewers() {
  nvIn.resizeListener();
  nvOut.resizeListener();
}

function setFrameUi(nt, labels) {
  const slider = $("frame");
  slider.max = String(Math.max(0, nt - 1));
  slider.value = "0";
  slider.disabled = nt <= 1;
  $("frame-label").textContent = labels[0] ?? "";
}

async function loadModel(name) {
  status(`loading ${name}…`);
  let meta;
  try {
    meta = await loadBundle(name);
  } catch (e) {
    status(`could not load bundle "${name}" (${e.message})`, true);
    return;
  }

  for (const v of [...nvIn.volumes]) nvIn.removeVolume(v);
  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  outputVolumes = [];
  shownOutput = null;
  lastMaps = null;
  $("output").hidden = true;
  $("output").replaceChildren();
  $("voxel-title").textContent = "Voxel — click either viewer";
  $("voxel-value").textContent = "";
  $("cal-min").value = "";
  $("cal-max").value = "";
  $("curve-note").textContent = "";
  clearCurve();
  enumFields = new Map((meta.enums ?? []).map((e) => [e.key, e.values]));
  wheelAccum = 0;
  setEditorText(meta.config);

  const [nx, ny, nz, nt] = meta.dims;
  let volume, maskVolume;
  try {
    volume = await nvIn.addVolumeFromUrl({
      url: `./data/${meta.files.data}`,
      name: meta.model,
      colormap: "gray",
      colorbarVisible: false,
    });
  } catch (e) {
    status(`could not load "${meta.files.data}" (${e.message})`, true);
    return;
  }
  let maskU8 = null;
  if (meta.files.mask) {
    try {
      maskVolume = await NVImage.loadFromUrl({ url: `./data/${meta.files.mask}` });
      maskU8 = readMask(maskVolume, nx, ny, nz);
    } catch (e) {
      status(`could not load "${meta.files.mask}" (${e.message})`, true);
      return;
    }
  }

  // `files.aux` is a general mechanism: whatever auxiliary inputs the recipe
  // resolved (none, one, or several), load every one and hand it to
  // fit_volume (a flat map, for the whole slice) and to forward() (one
  // scalar, for whichever voxel is clicked) — never keyed on a model or aux
  // name.
  const auxFlat = {};
  const auxVolumes = {};
  for (const [auxName, filename] of Object.entries(meta.files.aux ?? {})) {
    try {
      const auxVolume = await NVImage.loadFromUrl({ url: `./data/${filename}` });
      auxFlat[auxName] = Array.from(readScalarVolume(auxVolume, nx, ny, nz));
      auxVolumes[auxName] = auxVolume;
    } catch (e) {
      status(`could not load "${filename}" (${e.message})`, true);
      return;
    }
  }

  nvIn.setSliceType(nvIn.sliceTypeAxial);
  nvOut.setSliceType(nvOut.sliceTypeAxial);
  sizeViewers();
  nvIn.drawScene();

  setFrameUi(nt, meta.labels);
  current = { meta, volume, maskU8, auxFlat, auxVolumes, frame: 0 };
  $("fit").disabled = !wasm;
  status(`${meta.title}: ${nt} volumes, ${nx}×${ny}`);
}

function onFrameChange() {
  if (!current) return;
  const t = Number($("frame").value);
  current.frame = t;
  nvIn.setFrame4D(current.volume.id, t);
  $("frame-label").textContent = current.meta.labels[t] ?? "";
}

// Jumps to frame `t` (NiiVue's own `setFrame4D`, the same call `onFrameChange`
// makes from the slider) and syncs the slider + label to match, so the wheel
// and the slider always agree on where they are.
function goToFrame(t) {
  $("frame").value = String(t);
  onFrameChange();
}

// The progress track is a permanent fixture above "Fit slice" (an empty
// track at idle, not an element that appears/disappears and reflows the
// page); only its fill width and the "active" stripe animation change.
function showProgress() {
  $("progress-bar").classList.add("active");
  setProgress(0);
}
function setProgress(pct) {
  $("progress-bar").style.width = `${Math.max(0, Math.min(100, pct))}%`;
}
function hideProgress() {
  $("progress-bar").classList.remove("active");
  setProgress(0);
}
// Lets the browser paint (and stay responsive to input) between fit blocks —
// a plain microtask/`setTimeout(0)` does not reliably yield before the next
// paint in every engine, but a rAF round-trip does.
function nextFrame() {
  return new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 0)));
}

// `fit_volume` is one synchronous call with no progress callback across the
// wasm boundary, so real (not simulated) progress requires splitting the work
// ourselves: fit contiguous row-blocks of the slice — `x` is the slowest-
// varying axis in the C-order `[nx,ny,nz,nt]`/`[nx,ny,nz]` layout `data`/
// `maskU8`/`auxFlat` already use, so a row range is a contiguous subarray —
// and stitch each block's returned maps into the full-size buffers, yielding
// to the event loop between blocks so the progress bar paints and the page
// stays responsive. Each block is an independent voxelwise fit, so the
// stitched result is exactly the single-call result (verified by `probes`).
async function fitVolumeWithProgress(nx, ny, nz, nt, data, maskU8, auxFlat) {
  const spatial = nx * ny * nz;
  const blocks = Math.min(nx, 24);
  const rowsPerBlock = Math.max(1, Math.ceil(nx / blocks));
  let maps = null;
  for (let rowStart = 0; rowStart < nx; rowStart += rowsPerBlock) {
    const rowEnd = Math.min(nx, rowStart + rowsPerBlock);
    const rows = rowEnd - rowStart;
    const lo = rowStart * ny * nz;
    const hi = rowEnd * ny * nz;
    const blockData = data.subarray(lo * nt, hi * nt);
    const blockMask = maskU8 ? maskU8.subarray(lo, hi) : undefined;
    const blockAux = {};
    for (const [k, v] of Object.entries(auxFlat)) blockAux[k] = v.slice(lo, hi);
    const raw = wasm.fit_volume(
      editor.text,
      blockData,
      Uint32Array.from([rows, ny, nz, nt]),
      JSON.stringify(current.meta.volume_ids),
      blockMask,
      JSON.stringify(blockAux),
    );
    const blockMaps = Object.fromEntries(raw);
    if (!maps) {
      maps = {};
      for (const name of Object.keys(blockMaps)) maps[name] = new Float64Array(spatial).fill(NaN);
    }
    for (const [name, flat] of Object.entries(blockMaps)) maps[name].set(flat, lo);
    setProgress((rowEnd / nx) * 100);
    await nextFrame();
  }
  return maps ?? {};
}

async function fitSlice() {
  if (!current) { status("pick a model first"); return; }
  if (!wasm) { status("wasm unavailable — build the package to fit", true); return; }
  if (!editor.valid) {
    status("recipe YAML is invalid — fix it before fitting", true);
    return;
  }
  const { meta, volume, maskU8, auxFlat } = current;
  const [nx, ny, nz, nt] = meta.dims;
  status("fitting…");
  showProgress();
  $("fit").disabled = true;
  const t0 = performance.now();
  const data = readVolumeSeries(volume, nx, ny, nz, nt);
  let maps;
  try {
    maps = await fitVolumeWithProgress(nx, ny, nz, nt, data, maskU8, auxFlat);
  } catch (e) {
    status(`fit failed: ${e?.message ?? e}`, true);
    hideProgress();
    $("fit").disabled = false;
    return;
  }
  lastMaps = maps;

  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  outputVolumes = [];
  for (const o of meta.outputs) {
    const flat = maps[o.name];
    if (!flat) continue;
    const vol = buildMapVolume(volume, flat, nx, ny, nz, o.name, o.unit);
    outputVolumes.push({
      name: o.name,
      unit: o.unit,
      volume: vol,
      defaultCalMin: vol.cal_min,
      defaultCalMax: vol.cal_max,
    });
  }

  const select = $("output");
  select.replaceChildren();
  for (const o of outputVolumes) {
    const opt = document.createElement("option");
    opt.value = o.name;
    opt.textContent = `${o.name}${o.unit ? ` [${o.unit}]` : ""}`;
    select.append(opt);
  }
  select.hidden = outputVolumes.length <= 1;
  showOutput(outputVolumes[0]?.name);

  status(`fitted in ${Math.round(performance.now() - t0)} ms`);
  hideProgress();
  $("fit").disabled = false;
  if (current.lastVox) plotVoxel(current.lastVox.x, current.lastVox.y, current.lastVox.z);
}

function seedCalRangeInputs(entry) {
  $("cal-min").value = entry.volume.cal_min;
  $("cal-max").value = entry.volume.cal_max;
}

function showOutput(name) {
  const entry = outputVolumes.find((o) => o.name === name);
  for (const v of [...nvOut.volumes]) nvOut.removeVolume(v);
  shownOutput = entry ?? null;
  if (!entry) return;
  nvOut.addVolume(entry.volume);
  const cmapSelect = $("colormap");
  const preferred = CMAP_BY_UNIT[entry.unit] ?? "inferno";
  const cmap = availableColormaps.includes(preferred) ? preferred : availableColormaps[0];
  if (availableColormaps.includes(cmap)) cmapSelect.value = cmap;
  nvOut.setColormap(entry.volume.id, cmapSelect.value || cmap);
  nvOut.opts.isColorbar = true;
  seedCalRangeInputs(entry);
  nvOut.drawScene();
  if (current?.lastVox) updateVoxelValue(current.lastVox.x, current.lastVox.y, current.lastVox.z);
}

function onColormapChange() {
  const entry = outputVolumes.find((o) => o.name === $("output").value) ?? outputVolumes[0];
  if (!entry) return;
  nvOut.setColormap(entry.volume.id, $("colormap").value);
  nvOut.drawScene();
}

// Reader-adjustable colour scale: min/max feed `volume.cal_min`/`cal_max`
// directly (the same fields NiiVue's own auto windowing sets), so the
// colorbar — which reads off the volume — tracks the change for free.
function applyCalRange() {
  if (!shownOutput) return;
  const min = Number($("cal-min").value);
  const max = Number($("cal-max").value);
  if (!Number.isFinite(min) || !Number.isFinite(max)) return;
  shownOutput.volume.cal_min = min;
  shownOutput.volume.cal_max = max;
  nvOut.updateGLVolume();
  nvOut.drawScene();
}

function resetCalRange() {
  if (!shownOutput) return;
  shownOutput.volume.cal_min = shownOutput.defaultCalMin;
  shownOutput.volume.cal_max = shownOutput.defaultCalMax;
  seedCalRangeInputs(shownOutput);
  nvOut.updateGLVolume();
  nvOut.drawScene();
}

function populateColormaps() {
  const select = $("colormap");
  select.replaceChildren();
  const have = new Set(nvOut.colormaps());
  availableColormaps = CANDIDATE_COLORMAPS.filter((c) => have.has(c));
  if (availableColormaps.length === 0) availableColormaps = ["gray"];
  for (const name of availableColormaps) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    select.append(opt);
  }
}

function clearCurve() {
  const c = $("curve");
  const ctx = c.getContext("2d");
  ctx.clearRect(0, 0, c.width, c.height);
}

// Value of the currently-displayed map at `(x, y, z)`, shown beside the
// fitted-curve parameters — updates on every crosshair move, including while
// dragging (`onLocation` calls this on every `onLocationChange`).
function updateVoxelValue(x, y, z) {
  const el = $("voxel-value");
  if (!shownOutput) {
    el.textContent = "";
    return;
  }
  const v = shownOutput.volume.getValue(x, y, z, 0);
  const unit = shownOutput.unit ? ` ${shownOutput.unit}` : "";
  el.textContent = Number.isFinite(v)
    ? `${shownOutput.name} = ${v.toPrecision(3)}${unit} at (${x}, ${y})`
    : `${shownOutput.name} = no fit at (${x}, ${y})`;
}

function plotVoxel(x, y, z) {
  if (!current) return;
  current.lastVox = { x, y, z };
  const { meta, volume, auxVolumes } = current;
  const [nx, ny, nz, nt] = meta.dims;
  $("voxel-title").textContent = `Voxel (${x}, ${y})`;
  updateVoxelValue(x, y, z);
  if (!lastMaps) {
    $("curve-note").textContent = "fit the slice first, then click a voxel";
    clearCurve();
    return;
  }
  // `lastMaps` carries every entry `fit_volume` returns — the model's full
  // `output_names()`, including diagnostics that never make it into
  // `meta.outputs` (that list is filtered to quantitative maps only, for the
  // fitted-map viewer). A curve needs the fitted *parameters*, so the real
  // question is whether the fit result has them, not whether they happen to
  // be drawable maps.
  const idx = (x * ny + y) * nz + z;
  if (!meta.params.every((p) => p in lastMaps)) {
    const missing = meta.params.filter((p) => !(p in lastMaps));
    $("curve-note").textContent =
      `this model's fit does not report ${missing.join(", ")}, so no fitted ` +
      "curve is available for it.";
    clearCurve();
    return;
  }
  const params = meta.params.map((p) => lastMaps[p][idx]);
  if (params.some((v) => !Number.isFinite(v))) {
    $("curve-note").textContent = "no fit at that voxel (outside mask or fit failed)";
    clearCurve();
    return;
  }
  const measured = [];
  for (let t = 0; t < nt; t++) measured.push(volume.getValue(x, y, 0, t));
  // forward() takes one scalar per aux name (a single voxel), unlike
  // fit_volume's flat-array-per-name contract.
  const voxelAux = {};
  for (const [auxName, auxVolume] of Object.entries(auxVolumes)) {
    voxelAux[auxName] = auxVolume.getValue(x, y, z, 0);
  }
  const predicted = JSON.parse(
    wasm.forward(editor.text, Float64Array.from(params), JSON.stringify(voxelAux)),
  );
  const values = Array.isArray(predicted)
    ? predicted.map((s) => s.value)
    : meta.volume_ids.map((r) => predicted[r]);
  drawCurve(measured, values);
  $("curve-note").textContent = meta.params
    .map((p, k) => `${p} = ${params[k].toPrecision(3)}`)
    .join(", ");
}

function drawCurve(measured, predicted) {
  const c = $("curve");
  const dpr = window.devicePixelRatio || 1;
  const w = c.clientWidth || 380;
  const h = c.clientHeight || 170;
  c.width = w * dpr;
  c.height = h * dpr;
  const ctx = c.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const pad = 28;
  const all = measured.concat(predicted).filter(Number.isFinite);
  const lo = Math.min(...all), hi = Math.max(...all);
  const sx = (k) => pad + (k / Math.max(1, measured.length - 1)) * (w - 2 * pad);
  const sy = (v) => h - pad - ((v - lo) / (hi - lo || 1)) * (h - 2 * pad);
  const dark = window.matchMedia?.("(prefers-color-scheme: dark)").matches;
  ctx.strokeStyle = dark ? "#30363d" : "#c7ced6";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(pad, pad);
  ctx.lineTo(pad, h - pad);
  ctx.lineTo(w - pad, h - pad);
  ctx.stroke();
  ctx.strokeStyle = "#f0883e";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  predicted.forEach((v, k) => (k ? ctx.lineTo(sx(k), sy(v)) : ctx.moveTo(sx(k), sy(v))));
  ctx.stroke();
  ctx.fillStyle = "#38c0cf";
  measured.forEach((v, k) => {
    ctx.beginPath();
    ctx.arc(sx(k), sy(v), 2.8, 0, 2 * Math.PI);
    ctx.fill();
  });
  ctx.fillStyle = dark ? "#9aa7b2" : "#7c8797";
  ctx.font = "11px -apple-system, BlinkMacSystemFont, sans-serif";
  ctx.fillText("● measured", pad, 14);
  ctx.fillText("— forward model", pad + 78, 14);
}

function onLocation(loc) {
  if (!current || !loc?.vox) return;
  const [x, y, z] = loc.vox.map((v) => Math.round(v));
  const [nx, ny, nz] = current.meta.dims;
  if (x < 0 || y < 0 || z < 0 || x >= nx || y >= ny || z >= nz) return;
  plotVoxel(x, y, z);
}

async function main() {
  await nvIn.attachTo("gl-in");
  await nvOut.attachTo("gl-out");
  // Otherwise the canvas backing store renders at 1x and is upscaled by CSS
  // to its layout size — soft/blurry on any HiDPI (retina) display,
  // regardless of how much native resolution the bundle ships. NiiVue's own
  // `resizeListener` (already called on every model load and viewer resize)
  // keeps the backing store matched to `devicePixelRatio` once this is set.
  nvIn.setHighResolutionCapable(true);
  nvOut.setHighResolutionCapable(true);
  populateColormaps();

  // Synced crosshairs both ways, so dragging in either viewer moves the
  // other; click handling is registered on both instances too, so a click
  // on the fitted map updates the voxel curve exactly as one on the inputs
  // viewer does.
  nvIn.broadcastTo([nvOut], { "2d": true, "3d": true });
  nvOut.broadcastTo([nvIn], { "2d": true, "3d": true });
  nvIn.onLocationChange = onLocation;
  nvOut.onLocationChange = onLocation;

  wasm = await loadWasm();

  let index;
  try {
    index = await (await fetchOrThrow("./data/index.json")).json();
  } catch (e) {
    status(`could not load ./data/index.json (${e.message})`, true);
    return;
  }

  const select = $("model");
  for (const name of index.models) {
    let meta;
    try {
      meta = await loadBundle(name);
    } catch (e) {
      status(`could not load bundle "${name}" (${e.message})`, true);
      continue;
    }
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = meta.title;
    select.append(opt);
  }

  select.onchange = () => loadModel(select.value);
  $("frame").oninput = onFrameChange;
  $("fit").onclick = fitSlice;
  $("output").onchange = (e) => showOutput(e.target.value);
  $("colormap").onchange = onColormapChange;
  $("tab-form").onclick = () => showTab("form");
  $("tab-yaml").onclick = () => showTab("yaml");
  $("cfg-yaml").oninput = (e) => setEditorText(e.target.value);
  $("cal-min").onchange = applyCalRange;
  $("cal-max").onchange = applyCalRange;
  $("cal-reset").onclick = resetCalRange;

  // Wheel-to-scrub, alongside the existing slider: a reader hovering the
  // inputs viewer steps through frames without reaching for the slider,
  // useful once a model ships several volumes. Captured (not bubble-phase)
  // and stopped here, ahead of NiiVue's own wheel-to-zoom handler on the
  // canvas — this viewer's wheel gesture means "step frames", not "zoom the
  // slice" (the vendored build's own wheel handling is for slice zoom/scroll
  // and click-to-segment, not 4D frame stepping, so there is no built-in
  // gesture to opt into for this instead).
  //
  // A single mouse-wheel notch and a single trackpad two-finger gesture both
  // arrive as a *stream* of wheel events (a trackpad especially fires many
  // small ones), so stepping on every event blows through several frames per
  // gesture. Accumulate `deltaY` and only step once it crosses a threshold —
  // tuned to the ~100-120 one Chrome/Firefox mouse-wheel notch reports, and
  // large enough that one full trackpad swipe is one frame, not several.
  $("viewer-in").addEventListener(
    "wheel",
    (e) => {
      if (!current) return;
      const [, , , nt] = current.meta.dims;
      if (nt <= 1) return;
      e.preventDefault();
      e.stopPropagation();
      wheelAccum += e.deltaY;
      if (Math.abs(wheelAccum) < WHEEL_STEP_THRESHOLD) return;
      const dir = wheelAccum > 0 ? 1 : -1;
      wheelAccum = 0;
      const id = current.volume.id;
      const t = Math.min(nt - 1, Math.max(0, nvIn.getFrame4D(id) + dir));
      if (t === nvIn.getFrame4D(id)) return;
      goToFrame(t);
    },
    { passive: false, capture: true },
  );

  if (select.options.length) {
    await loadModel(select.value);
    if (wasm) status("ready — press Fit slice");
  }
}

main();

// Read-only state accessor for automated smoke-testing; no UI depends on this.
window.__playground = { maps: () => lastMaps, editor: () => editor };
